style.css:
@-moz-document domain("google.com") {
/* Background */
  body, html {
    background: url("https://i.pinimg.com/originals/f9/37/27/f93727f4ff7a5f376b5cc406cb579d70.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Dark overlay to improve contrast */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(255, 240, 245, 0.4); /* light pink overlay */
    z-index: -1;
  }

  /* Hide default Google logo */
  img[alt="Google"] {
    display: none !important;
  }

  /* Replace with Hello Kitty logo */
  #hplogo {
    background: url("https://upload.wikimedia.org/wikipedia/en/1/12/Hello_Kitty_character_portrait.png") no-repeat center;
    background-size: contain;
    width: 272px !important;
    height: 92px !important;
    display: block !important;
    margin: 0 auto;
  }

  /* Input box */
  input.gLFyf {
    background: #fff0f5 !important;
    border: 2px solid #ff69b4 !important;
    color: #d63384 !important;
    border-radius: 20px !important;
    padding: 10px !important;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
  }

  /* Buttons */
  input[type="submit"], .RNmpXc {
    background-color: #ffb6c1 !important;
    color: #fff !important;
    border: none !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    padding: 8px 16px !important;
    margin: 4px !important;
    transition: background 0.3s ease;
  }

  input[type="submit"]:hover, .RNmpXc:hover {
    background-color: #ff69b4 !important;
  }

  /* Footer */
  #fbar, .fbar {
    background: rgba(255, 240, 245, 0.7) !important;
    color: #ff69b4 !important;
  }

  /* Links */
  a {
    color: #ff69b4 !important;
  }
}
